from collections import Counter
# rectangles multiset: (h,w,color)
rects=[(6,2,4),(2,5,1),(1,4,6),(1,4,6),(3,2,7),(2,2,8),(1,1,0)]
# generate placements on mask a==2
placements=[]
for idx,(h,w,c) in enumerate(rects):
 for r in range(15-h+1):
  for col in range(7-w+1):
   cells={(rr,col+cc) for rr in range(r,r+h) for cc in range(w)}
   if all(a[x,y]==2 for x,y in cells): placements.append((idx,r,col,c,cells))
print('placements by idx',Counter(p[0] for p in placements))

target={(r,c) for r in range(15) for c in range(7) if a[r,c]==2}
# placements by rect type
P={i:[p for p in placements if p[0]==i] for i in range(len(rects))}
sols=[]
def back(remaining_types, free, chosen):
 if not free:
  if not remaining_types: sols.append(chosen.copy())
  return
 # choose first free cell, constrain placements containing it
 cell=min(free)
 opts=[]
 for i in set(remaining_types):
  for p in P[i]:
   if cell in p[4] and p[4]<=free: opts.append((i,p))
 for i,p in opts:
  rt=list(remaining_types); rt.remove(i)
  back(rt,free-p[4],chosen+[p])
back(list(range(len(rects))),target,[])
print('nsol',len(sols))
for sol in sols[:5]: print([(p[0],p[1],p[2],p[3]) for p in sol])
